#include "NewQualitySupport.h"
int main(int argc,char**argv){std::cout<<std::unitbuf;juce::ScopedJuceInitialiser_GUI gui;int pass=0,fail=0;auto check=[&](bool ok,const char*name){std::cout<<(ok?"PASS ":"FAIL ")<<name<<'\n';ok?++pass:++fail;};try{Audio tone;tone.rate=48000;for(auto&v:tone.v){v.resize(96000);for(size_t i=0;i<v.size();++i)v[i]=float(.25*std::sin(2*juce::MathConstants<double>::pi*1000*i/tone.rate));}Audio quiet=tone;for(auto&v:quiet.v)std::fill(v.begin(),v.end(),0.f);
 auto gain=[&](const AuditRender&r,const Audio&source,int begin=24000,int end=72000){Stats s;for(int c=0;c<2;++c)for(int i=begin;i<end;++i)s.add(source.v[c][i],r.wet.v[c][i+r.latency]);return std::pair<double,double>(std::sqrt(s.out/s.in),s.nullRms());};
 auto off=render(tone,quiet,-1,{});check(gain(off,tone).second<3e-6,"musical carrier allOFF is transparent after declared PDC");
 for(int mode:{0,2}){auto out=render(tone,quiet,mode,[=](auto&p){p.setCustomCurve(mode,flat(.9f));});const double measured=gain(out,tone).first;std::cout<<"MEASURE envelope90 mode"<<mode<<" gain="<<measured<<" expected0.9\n";check(std::abs(measured-.9)<.003,("amplitude envelope90 preserves90percent gain sector"+std::to_string(mode)).c_str());}
 auto closed=render(tone,quiet,0,[](auto&p){p.setCustomCurve(0,flat(0));});check(gain(closed,tone).first<.001,"Amount100 still closes plateau by at least60dB");
 auto half=render(tone,quiet,0,[](auto&p){auto s=flat(0);s.amount=50;p.setCustomCurve(0,s);});check(std::abs(20*std::log10(gain(half,tone).first)+30)<.05,"Amount50 still has minus30dB plateau floor");
 auto unity=render(tone,quiet,-2,[](auto&p){for(int k=0;k<6;++k){p.setCustomCurve(k,flat(1));p.setSectorParameter(k,"bands",2);p.setSectorParameter(k,"phaseMode",0);}});check(gain(unity,tone).second<3e-6,"all6 minimum-phase complementary bands retain unity and phase");
 double biggest=0;for(int harmonic=2;harmonic<=8;++harmonic){double re=0,im=0;for(int i=24000;i<72000;++i){const double ph=2*juce::MathConstants<double>::pi*1000*harmonic*i/48000;const float y=unity.wet.v[0][i+unity.latency];re+=y*std::cos(ph);im+=y*std::sin(ph);}biggest=std::max(biggest,2*std::hypot(re,im)/48000);}std::cout<<"MEASURE unity maximum harmonics2..8="<<biggest<<'\n';check(biggest<1e-6,"unity six-engine path does not introduce measurable carrier harmonics above minus120dBFS");
 Audio constant=tone;for(auto&v:constant.v)std::fill(v.begin(),v.end(),.25f);auto recovery=render(constant,quiet,0,{});const int middle=int(std::round((60./145+.085)*48000));double mid=0;for(int i=middle-24;i<middle+24;++i)mid+=recovery.wet.v[0][i+recovery.latency]/.25;mid/=48;std::cout<<"MEASURE recovery85ms="<<mid<<" expectedabout0.5\n";check(std::abs(mid-.5)<.035,"INIT recovery midpoint follows amplitude curve instead of remaining near minus30dB");
 Stats late;for(int i=24000;i<72000;++i){const double phase=std::fmod(i/48000.,60./145);if(phase>.22&&phase<.38)late.add(.25,recovery.wet.v[0][i+recovery.latency]);}check(late.nullRms()<3e-6,"INIT off-hit open window returns to original signal without hidden loss");

 for(int linked:{0,1}){auto bands=render(tone,quiet,2,[=](auto&p){auto m=flat(.5f);m.amount=80;p.setCustomCurve(2,m);p.setSectorParameter(2,"bands",2);p.setSectorParameter(2,"linked",float(linked));for(int b=0;b<3;++b){auto c=flat(.5f);c.amount=50;p.setBandCurveSnapshot(2,b,c);const char*names[]={"lowAmount","midAmount","highAmount"};p.setSectorParameter(2,names[b],50);const char*old[]={"bandLow","bandMid","bandHigh"};set(p,old[b],.6f);}});const double amount=80*.5*.6*(linked?1:.5),floor=std::pow(10.,-3*amount/100),expected=floor+(1-floor)*.5;const double actual=gain(bands,tone).first;std::cout<<"MEASURE composedBandAmount linked"<<linked<<" gain="<<actual<<" expected="<<expected<<'\n';check(std::abs(actual-expected)<.0001,("band Amount composes before gain law linked"+std::to_string(linked)).c_str());}
 auto inverseOwner=std::make_unique<OpenDuckProcessor>();auto&inv=*inverseOwner;inv.prepareToPlay(48000,257);double worst=0;int cases=0;bool allFinite=true;
 for(int mode=0;mode<6;++mode){auto m=flat(.13f);m.points[1].y=.89f;m.linear=true;m.attack=17;m.release=210;m.phase=13;m.length=.8f;inv.setCustomCurve(mode,m);inv.setSectorParameter(mode,"bands",2);inv.setSectorParameter(mode,"offset",17);inv.setSectorParameter(mode,"lookahead",9);inv.setSectorParameter(mode,"swing",37);for(int b=0;b<3;++b){auto curve=flat(.2f+.03f*b);curve.points[1].y=.7f+.05f*b;curve.linear=true;curve.amount=33+29*b;curve.attack=8+2*b;curve.release=100+10*b;curve.phase=-4+3*b;inv.setBandCurveSnapshot(mode,b,curve);const char*names[]={"lowAmount","midAmount","highAmount"};inv.setSectorParameter(mode,names[b],35+30*b);}set(inv,"bandLow",.4f);set(inv,"bandMid",.7f);set(inv,"bandHigh",.9f);
 for(int linked:{0,1})for(float amount:{20.f,55.f,100.f})for(float character:{0.f,.5f,1.f})for(float scalar:{.23f,.76f}){inv.setSectorParameter(mode,"linked",float(linked));set(inv,OpenDuckProcessor::curveParameterId("amount",mode),amount);inv.setSectorParameter(mode,"character",character);set(inv,"spectralDepth",scalar);set(inv,"grooveDepth",scalar);for(int band=-1;band<3;++band)for(float cycle:{.07f,.17f,.36f,.72f,.94f}){const float x=inv.previewCycleToRaw(mode,cycle,band);const bool independent=band>=0&&!linked;const float lo=independent?.2f+.03f*band:.13f,hi=independent?.7f+.05f*band:.89f;const double expected=lo+(hi-lo)*x;const float g=inv.previewCurveGain(mode,cycle,band),back=inv.previewGainToCurveEnvelope(mode,cycle,g,band);allFinite&=std::isfinite(g)&&std::isfinite(back);worst=std::max(worst,std::abs(back-expected));++cases;}}
 }
 std::cout<<"MEASURE preview/inverse "<<cases<<" cases worstError="<<worst<<'\n';check(allFinite&&worst<.0002,"canvas preview/inverse preserves points across six modes, linked/independent bands, partial Amount, Character, scalar depth and time mapping");

 Audio spectralMain=tone,key=tone;const double bin=48000./1024;for(int c=0;c<2;++c)for(int i=0;i<96000;++i)spectralMain.v[c][i]=float(.25*std::sin(2*juce::MathConstants<double>::pi*63*bin*i/48000));std::array<AuditRender,4>spectral;
 for(int type=0;type<4;++type){for(int i=0;i<96000;++i){const float a=float(.7*std::sin(2*juce::MathConstants<double>::pi*3*bin*i/48000)),b=float(.7*std::sin(2*juce::MathConstants<double>::pi*21*bin*i/48000));key.v[0][i]=type==0||type==1?b:type==2?a:b;key.v[1][i]=type==0?b:type==1?-b:type==2?b:a;}spectral[type]=render(spectralMain,key,1,[](auto&p){p.setCustomCurve(1,flat(0));set(p,"spectralLow",20);set(p,"spectralHigh",20000);});}
 const double unrelated=gain(spectral[2],spectralMain).first,pure=gain(spectral[0],spectralMain).first;std::cout<<"MEASURE independent stereo key unrelated gain="<<unrelated<<" pure-key gain="<<pure<<'\n';check(unrelated>.995,"Spectral independent stereo key preserves a frequency absent from both key channels");check(std::abs(unrelated-pure)<.003,"Spectral unrelated-frequency retention agrees with pure double-mono sidechain");
 auto renderDifference=[&](const AuditRender&a,const AuditRender&b){double sum=0;for(int i=24000;i<72000;++i){double d=a.wet.v[0][i+a.latency]-b.wet.v[0][i+b.latency];sum+=d*d;}return std::sqrt(sum/48000);};
 const double swapped=renderDifference(spectral[2],spectral[3]),opposite=renderDifference(spectral[0],spectral[1]);std::cout<<"MEASURE Spectral swapped RMS="<<swapped<<" antiphase RMS="<<opposite<<'\n';check(swapped<1e-6,"Spectral stereo key is invariant when left and right channels are exchanged");check(opposite<1e-6,"Spectral antiphase key retains the double-mono mask without cancellation");
 }catch(const std::exception&e){std::cout<<"FAIL exception "<<e.what()<<'\n';++fail;}std::cout<<"RESULT "<<pass<<" passed, "<<fail<<" failed\n";return fail?1:0;}
